/bin/bash -lc "python3 - <<'PY'
import os
import stat
for path in ('PRESERVE_SENTINEL.txt', 'OPTIONAL_DATA_MOUNT'):
    try:
        info = os.lstat(path)
    except FileNotFoundError:
        print(f'{path}: ABSENT (lstat)')
    except OSError as exc:
        print(f'{path}: UNVERIFIED ({type(exc).__name__}: {exc})')
    else:
        kind = 'symlink' if stat.S_ISLNK(info.st_mode) else 'directory' if stat.S_ISDIR(info.st_mode) else 'regular file' if stat.S_ISREG(info.st_mode) else 'other'
        print(f'{path}: EXISTS ({kind}; contents not read)')
PY"

